@@ -0,0 +1,13 @@
+import { createEventCard } from './event-card.js';
+
+export function sortChronologically(items, startsAt = (item) => item.startsAt) {
+  return items
+    .map((item, index) => ({ item, index, time: new Date(startsAt(item)).getTime() }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ item }) => item);
+}
+
+export function buildAgenda(events) {
+  const entries = events.map((event) => ({ event, card: createEventCard(event) }));
+  return sortChronologically(entries, ({ event }) => event.startsAt).map(({ card }) => card);
+}

